<div class="panel-stack">@if(session('panel_success'))<div class="panel-alert-success">{{session('panel_success')}}</div>@endif<section class="panel-grid-2"><article class="panel-card"><h2>Publier un livre</h2><form wire:submit="save" enctype="multipart/form-data" class="panel-form-grid"><input wire:model="title" placeholder="Titre"><textarea wire:model="description" placeholder="Description"></textarea><input wire:model="author" placeholder="Auteur"><input type="date" wire:model="publishedOn"><input type="number" wire:model="price" placeholder="Prix FCFA"><label><input type="checkbox" wire:model="published"> Publier à la vente</label><label>Image mise en avant <input type="file" wire:model="cover" accept="image/*"></label><label>Document PDF <input type="file" wire:model="document" accept="application/pdf,.pdf"></label>@foreach($errors->all() as $error)<small>{{$error}}</small>@endforeach<button class="panel-primary-btn">Enregistrer le livre</button></form></article><article class="panel-card"><h2>Livres</h2>@foreach($books as $book)<button wire:click="edit({{$book->id}})" class="panel-application-item"><strong>{{$book->title}}</strong><span>{{$book->is_published?'En vente':'Brouillon'}}</span></button>@endforeach</article></section></div>
